// Embedded in exported Function nodes: no external JS module is needed on import.
const DEVICE_ID = "dev-thermo-001";
const WEATHER_MAX_AGE = 1800000;
const isNumber = (v) => typeof v === "number" && Number.isFinite(v);
const inRange = (v, min, max) => isNumber(v) && v >= min && v <= max;
function parseObject(value) {
    if (typeof value === "string") {
        if (value.length > 32768) throw Error("Message exceeds 32 KiB");
        value = JSON.parse(value);
    }
    if (!value || typeof value !== "object" || Array.isArray(value)) throw Error("Expected a JSON object");
    return value;
}
function validWeather(w) {
    return w && w.schemaVersion === 1 && w.deviceId === DEVICE_ID &&
        w.city === "Glasgow" && inRange(w.tempc, -60, 60) &&
        inRange(w.tempMinc, -60, 60) && inRange(w.tempMaxc, -60, 60) &&
        w.tempMinc <= w.tempc && w.tempc <= w.tempMaxc &&
        inRange(w.humidity, 0, 100) && typeof w.description === "string" &&
        w.description.length > 0 && w.description.length <= 200 &&
        inRange(w.sunrise, 1, 1e11) && inRange(w.sunset, 1, 1e11) &&
        w.sunrise < w.sunset && inRange(w.timestamp, 1e12, Date.now() + 300000) &&
        inRange(w.receivedAt, 1e12, Date.now() + 300000);
}
function weatherFresh(w) {
    return validWeather(w) && Date.now() - w.timestamp <= WEATHER_MAX_AGE &&
        Date.now() - w.receivedAt <= WEATHER_MAX_AGE;
}
function validSetpoint(s) {
    return s && s.schemaVersion === 1 && s.deviceId === DEVICE_ID &&
        s.unit === "C" && inRange(s.setpointC, -10, 35) &&
        inRange(s.timestamp, 1e12, Date.now() + 300000);
}
function reject(reason) {
    node.status({fill:"yellow", shape:"ring", text:reason});
    // Do not echo untrusted payloads/credentials into logs.
    node.warn(reason);
    return null;
}

// Prefer the complete OWM response (msg.data) over the palette's truncated tempc.
try {
    const raw = parseObject(msg.data);
    const kelvinToC = (v) => isNumber(v) ? Number((v - 273.15).toFixed(2)) : NaN;
    if (raw.sys?.country !== "GB" || !/glasgow/i.test(raw.name || "")) {
        return reject("Rejected weather for a different city");
    }
    const w = {
        schemaVersion: 1, deviceId: DEVICE_ID, city: "Glasgow",
        tempc: kelvinToC(raw.main?.temp),
        tempMinc: kelvinToC(raw.main?.temp_min),
        tempMaxc: kelvinToC(raw.main?.temp_max),
        humidity: raw.main?.humidity,
        description: raw.weather?.[0]?.description,
        sunrise: raw.sys?.sunrise, sunset: raw.sys?.sunset,
        timestamp: isNumber(raw.dt) ? raw.dt * 1000 : NaN,
        receivedAt: Date.now()
    };
    if (!weatherFresh(w)) return reject("Rejected invalid or stale OWM response");
    const previous = global.get("thermostat.weather");
    if (previous && w.timestamp < previous.timestamp) return reject("Ignored older OWM observation");
    global.set("thermostat.weather", {...w, raw});
    let history = global.get("thermostat.history") || [];
    history = history.filter(p => p.timestamp >= Date.now() - 3600000 && p.timestamp !== w.timestamp);
    history.push({timestamp:w.timestamp, tempc:w.tempc, humidity:w.humidity});
    history.sort((a,b) => a.timestamp - b.timestamp);
    global.set("thermostat.history", history.slice(-720));
    node.status({fill:"green", shape:"dot", text:w.tempc + " C | Glasgow cached"});
    return [{payload:JSON.stringify(w)}, {topic:"weather-updated"}];
} catch (_) {
    return reject("Invalid OWM response; keeping last good observation");
}

